<?php
declare(strict_types=1);
namespace App\Repository\Cms;
use App\Entity\Cms\CmsPage; use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository; use Doctrine\Persistence\ManagerRegistry; use Sylius\Component\Channel\Model\ChannelInterface;
final class CmsPageRepository extends ServiceEntityRepository { public function __construct(ManagerRegistry $r){parent::__construct($r,CmsPage::class);} public function findBySlug(string $slug,ChannelInterface $channel,string $locale):?CmsPage { return $this->createQueryBuilder('p')->addSelect('t','l','c')->join('p.translations','t')->join('p.layout','l')->join('p.channels','c')->andWhere('t.slug=:slug AND t.locale=:locale AND c=:channel')->setParameters(['slug'=>$slug,'locale'=>$locale,'channel'=>$channel])->getQuery()->getOneOrNullResult(); } /** @return list<CmsPage> */ public function sitemapPages(ChannelInterface $channel,string $locale):array{return $this->createQueryBuilder('p')->addSelect('t','l')->join('p.translations','t')->join('p.layout','l')->join('p.channels','c')->andWhere('c=:channel AND t.locale=:locale AND p.includeInSitemap=true AND t.robotsIndex=true')->setParameters(['channel'=>$channel,'locale'=>$locale])->getQuery()->getResult();} }
